            event.getBlock().getDrops().clear();
            Bukkit.getScheduler().runTaskLater(plugin, new Runnable(){
                public void run() {
                    event.getBlock().setType(originalOre);
                }
            }, 5*20L); // TODO: Change time

        }

    }

}

