public class Player
{
    //private Record playerRecord
    private double rating;
    private final String ID = "";
    private int ranking;
    public String name;
    private int losses;
    private int wins;
    private int draws;

    public Player(String name){
        rating = 1000.0;
        ranking = 0;
        name = name;
        losses = 0;
        wins = 0;
        draws = 0;
    }

    int getTotalGames(){
        int t = (wins+draws+losses);
        return t;
    }

    float getWinLossRatio(){
        float r = (wins/losses);
        return r;
    }

    int getWins(){
        return wins;
    }

    int getLosses(){
        return losses;
    }

    int getDraws(){
        return draws;
    }

    double getRating(){
        return rating;
    }

    String getID(){
        return ID ;
    }

    double getRanking(){
        return ranking;
    }

    String getName(){
        return name;
    }

    void setWins(int newWins){
        wins = newWins;
    }

    void setLosses(int newLosses){
        losses = newLosses;
    }

    void setDraws(int newDraws){
        draws = newDraws;
    }

    void setRating(double newRating){
        rating = newRating;
    }

    void setName(String newName){
        name = newName;
    }
}

